673 :         if (depth1 < depth2) {
674 :             int r = compareNodePointers(p1, depth1, p2.parent, depth2 - 1);
675 :             return r == 0 ? -1 : r;
676 :         }
677 :         if (depth1 > depth2) {
678 :             int r = compareNodePointers(p1.parent, depth1 - 1, p2, depth2);
679 :             return r == 0 ? 1 : r;
680 :         }
681 :         //henceforth depth1 == depth2:
682 :         if (p1 == p2 || p1 != null && p1.equals(p2)) {
683 :             return 0;
684 :         }
685 :         if (depth1 == 1) {
686 :             throw new JXPathException(
687 :                     "Cannot compare pointers that do not belong to the same tree: '"
688 :                     + p1 + "' and '" + p2 + "'");
689 :         }
690 :         int r = compareNodePointers(p1.parent, depth1 - 1, p2.parent, depth2 - 1);
691 :         return r == 0 ? p1.parent.compareChildNodePointers(p1, p2) : r;
692 :     }
